// «Orchestration турших самбар». Энэ файлыг өөрчлөх шаардлагагүй.
const output = document.getElementById("output");
function panel(cls, testid, title, lines) {
  const box = document.createElement("section");
  box.className = "call " + cls;
  box.dataset.testid = testid;
  const h = document.createElement("h2");
  h.textContent = title;
  box.append(h);
  for (const line of lines) {
    const p = document.createElement("pre");
    p.textContent = line;
    box.append(p);
  }
  output.append(box);
  return box;
}

// 2 replica, CPU 90%, зорилт 50% → өсгөнө.
window.UP = desiredReplicas(2, 90, 50, 1, 10);
// 4 replica, CPU 20%, зорилт 50% → багасгана.
window.DOWN = desiredReplicas(4, 20, 50, 1, 10);
// 5 replica, CPU 200%, зорилт 50% → max-д хязгаарлагдана.
window.CLAMP = desiredReplicas(5, 200, 50, 1, 6);

panel("ok", "up", "Ачаалал өндөр", ["desiredReplicas → " + window.UP]);
panel("ok", "down", "Ачаалал бага", ["desiredReplicas → " + window.DOWN]);
panel("ok", "clamp", "max-д хязгаарлагдсан", ["desiredReplicas → " + window.CLAMP]);
document.body.dataset.ready = "1";

function desiredReplicas(current, currentCpu, targetCpu, min, max) {
  const raw = Math.ceil(current * (currentCpu / targetCpu));
  return Math.max(min, Math.min(max, raw));
}
